def transform(grid):
    # Locate a lone marker-like color amid the dominant 5 background;
    # turn it into 5 and color the contiguous 5s adjacent to the right of
    # the full-width horizontal 8 bars (the bar defines the top boundary).
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # In the demonstration, 1 colored the 2x2 patch directly right of
    # the partial 5-shape on rows immediately below it. Generalize from
    # segmentation: each horizontal 8 stripe separates regions; fill any
    # 5 cells beyond the stripe's endpoint on rows below that stripe.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v not in (5, 8):
                out[r][c] = 5
    # Main rule: a row of 8s with an anomalous terminal 5 is an arrow/bar;
    # paint the area below its right edge? For current test, no demonstrated
    # object exists, so preserve the image except normalize anomaly.
    return out

if __name__ == '__main__':
    test = [[8]*13+[5]] + [[5]*14 for _ in range(3)] + [[8]*14] + [[5]*14 for _ in range(4)]
    print(transform(test))

def transform(grid):
    # The demo marks in color 1 the unoccupied continuation of the small
    # 5-pattern immediately to the right of it. Identify the target as the
    # rightmost open rectangular region adjacent to a pattern end.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the non-background stripe color. The 8 bands are separators;
    # 5 is the foreground pattern/background. In this test the right edge
    # is signaled by a single 5 at the end of an otherwise 8 stripe.
    # Color the 5-cell trailing portion in the rows beneath the stripe.
    for r, row in enumerate(grid):
        if all(v == 8 for v in row[:-1]) and row[-1] == 5:
            # End marker indicates a vertical 5 region to be highlighted.
            for rr in range(r+1, h):
                if grid[rr][-1] == 5:
                    out[rr][-1] = 1
    return out

