def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Rows containing a partial run of the dominant stripe color have that
    # run extended to the right with 1, beginning where the run ends.
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    stripe = next((v for v in set(vals) if v != bg), bg)
    for r, row in enumerate(grid):
        if stripe in row and bg in row and row[0] == stripe:
            # Locate the first transition from stripe to background; the
            # continuation of the stripe is highlighted through row end.
            c = 0
            while c < w and row[c] == stripe:
                c += 1
            if c < w and all(x == bg for x in row[c:]):
                for cc in range(c, w):
                    out[r][cc] = 1
    return out

