def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # For each row with a solid run of the non-background color, extend
    # its right edge in color 1 through the remaining cells.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next((x for x in counts if x != bg), bg)
    for r, row in enumerate(grid):
        c = 0
        while c < w and row[c] == fg:
            c += 1
        if 0 < c < w and all(x == bg for x in row[c:]):
            for cc in range(c, w):
                out[r][cc] = 1
    return out

