def transform(grid):
    # Rows forming two-line glyphs, separated by the uniform background:
    # recolor the incomplete long run according to the demo: the uninterrupted
    # run at right becomes 1 when adjoining the characteristic glyph pair.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        # Detect a row with predominantly background and a long terminal 5 run.
        if grid[r][-1] == 5:
            c = w - 1
            while c >= 0 and grid[r][c] == 5:
                c -= 1
            # Demo's altered segment is terminal run, at the top and bottom glyphs.
            if r == 0 or (r > 0 and all(v == 0 for v in grid[r-1])):
                for x in range(c+1, w):
                    out[r][x] = 1
    return out

def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        # Extend a row's rightmost colored segment through the remaining
        # background, highlighting that trailing continuation with color 1.
        nonbg = [c for c, v in enumerate(row) if v != bg]
        if nonbg:
            last = nonbg[-1]
            if last < len(row) - 1:
                for c in range(last + 1, len(row)):
                    out[r][c] = 1
    return out

