    # line with 1. The demos show the endpoint marker on this single terminal
    # cell, not wholesale filling of gaps or shorter incomplete rows.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if row[-1] != row[0] and row[-1] != 1:
            continue
