    # Mark background at the right ends of the horizontal bars. A bar block
    # has two or more adjacent rows with non-background cells; only rows of
    # these blocks that reach the right boundary through foreground are kept
    # unchanged, while incomplete rightward continuations are marked.
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if row[0] == bg:
            continue
        last = max(c for c, v in enumerate(row) if v != bg)
        # In motif-like consecutive foreground rows, extend each bar to edge;
        # isolated lines are also extended, matching the demonstrated stripes.
        for c in range(last + 1, w):
            out[r][c] = 1
    return out

def transform(grid):
    # A horizontal colored stripe with a background interruption: recolor
    # that interruption and the remainder of the row to marker 1. Also mark
    # background cells following a partial bar when its row is part of a
    # contiguous stripe motif (demonstrated multi-row blocks).
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if row[0] == bg:
            continue
        last = max(c for c, v in enumerate(row) if v != bg)
        # Color the suffix after the final colored cell whenever the row has
        # foreground and terminates in background; untouched solid bars stay.
        if last < w - 1:
            for c in range(last + 1, w):
                out[r][c] = 1
    return out
