def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # When repeated horizontal motifs occur, complete the later motif's
    # shortened bars with marker 1, leaving the reference motif unchanged.
    rows = [r for r, row in enumerate(grid) if fg in row]
    if rows:
        split = len(rows) // 2
        later = rows[split:]
        for r in later:
            row = grid[r]
            if row[0] != fg:
                continue
            last = max(c for c, v in enumerate(row) if v == fg)
            for c in range(last + 1, w):
                if row[c] == bg:
                    out[r][c] = 1
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # Repeated motif blocks: the later copy is completed to match the earlier
    # copy, with missing cells colored marker 1.
    # Locate repeated rows and use the earlier occurrence as reference.
