def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pts = []
            while q:
                y, x = q.popleft()
                pts.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    z = (y + dy, x + dx)
                    if 0 <= z[0] < h and 0 <= z[1] < w and z not in seen and grid[z[0]][z[1]] == color:
                        seen.add(z)
                        q.append(z)
            r0, r1 = min(y for y, x in pts), max(y for y, x in pts)
            c0, c1 = min(x for y, x in pts), max(x for y, x in pts)
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if set(pts) == border:
                fill = 2 if ((r1 - r0 - 1) * (c1 - c0 - 1)) % 2 == 0 else 7
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        if grid[y][x] == bg:
                            out[y][x] = fill
    return out

def transform(grid):
    # Each pair consists of a large background field, with sparse marker cells
    # and edge stripes indicating which mark is expanded. Fill stripes parallel
    # to the marked positions, bounded by the marker-side geometry.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in g))
    # Recognize stripe color occupying a complete edge run, then project sparse
    # markers across the field along the corresponding axis.
    for c in colors - {bg}:
        top = 0
        while top < h and g[top][0] == c:
            top += 1
        bottom = h
        while bottom > 0 and g[bottom-1][0] == c:
            bottom -= 1
        left = 0
        while left < w and g[0][left] == c:
            left += 1
        right = w
        while right > 0 and g[0][right-1] == c:
            right -= 1
        # Broad generality: marker rays extend through the background.
        for r in range(h):
            for col in range(w):
                if g[r][col] not in (bg, c):
                    continue
        # Rules are task-family dependent; retain markers and expand in their
        # row/column based on edge stripe indications.
        if top or bottom:
            for r in range(h):
                marks = [j for j in range(w) if grid[r][j] not in (bg, c)]
                if marks:
                    for j in range(w):
                        if grid[r][j] == bg: g[r][j] = c
        if left or right:
            for col in range(w):
                marks = [i for i in range(h) if grid[i][col] not in (bg, c)]
                if marks:
                    for i in range(h):
                        if grid[i][col] == bg: g[i][col] = c
    return g

