    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(v == c for row in grid for v in row))
    marker = next(c for c in colors if c != bg)
    pts = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker}
    # Select the marker component as the repeated motif.
    unseen = set(pts); comps=[]
