        q=[unseen.pop()]; comp=set(q)
        for r,c in q:
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in unseen: unseen.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
