def transform(grid):
    # A single-color separator splits the canvas; retain the larger patterned side.
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            color = row[0]
            if 0 < r < h - 1:
                region = grid[:r]
                break
    else:
        for c in range(w):
            col = [row[c] for row in grid]
            if len(set(col)) == 1:
                region = [row[:c] for row in grid]
                break
    # Dots are the least frequent color in the retained panel; background becomes 8/5.
    from collections import Counter
    counts = Counter(v for row in region for v in row)
    dot = min(counts, key=counts.get)
    return [[3 if v == dot else (8 if 8 in counts else 5) for v in row] for row in region]

