def transform(grid):
    # The left panel is the canvas; the right panel supplies sparse 9/6 marks.
    # The separator is a uniform column of 0; output is left panel's base color,
    # with positions marked by 6 in the right panel rendered as 3.
    sep = next(c for c in range(len(grid[0])) if len({row[c] for row in grid}) == 1 and grid[0][c] == 0)
    left = [row[:sep] for row in grid]
    right = [row[sep+1:] for row in grid]
    color_counts = {}
    for row in left:
        for v in row:
            color_counts[v] = color_counts.get(v, 0) + 1
    base = max(color_counts, key=color_counts.get)
    output=[]
    for r in range(len(grid)):
        output.append([3 if c < len(right[r]) and right[r][c] == 6 else base for c in range(sep)])
    return output

